INSERT INTO "char_abilities" VALUES(1003000100,3,2013401,'EX角色能力','[{"tid": 201340100, "trait_id": 201340101, "trait": {"id": 201340101, "trait_type": 17, "trait_value": 15, "desc": "搭乘单位含有「专用机、机动战士高达 THE ORIGIN」标签／「机动战士高达 THE ORIGIN」系列时，\n对敌方造成的损伤提升15%、\n自身机动力提升15%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000239, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 8, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000239, "trait_condition_set_id": 1000239, "group_id": "", "target": "Owner", "unit_tags": "1007", "unit_role": "", "unit_series": "30", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": [{"id": 1007, "name": "专用机"}], "series": {"id": 30, "world_id": 1, "name": "机动战士高达 THE ORIGIN", "desc": "宇宙世纪0068年，SIDE3，慕佐共和国。\n自护‧兹姆‧戴昆提倡进入宇宙后人类的革新，打算宣布彻底从地球联邦政府独立，却在议会讲台上演讲时突然倒下，撒手人寰。\n戴昆死后，他的亲信金巴‧拉路主张这是萨比家的阴谋。\n然而，为了掌握SIDE3──慕佐的实权，汤金‧索多‧萨比率领的萨比家在台面下越趋活跃。\n至今不曾述说的动乱历史即将揭晓，卡斯巴尔与阿尔黛西雅身为戴昆遗孤，将面临动荡时代下的曲折命运……", "icon": "series_0030", "sort": 1100, "schedule_id": 0, "scenario_stage_series_id": 0, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}, {"tid": 201340100, "trait_id": 201340102, "trait": {"id": 201340102, "trait_type": 11, "trait_value": 15, "desc": "", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000239, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 8, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000239, "trait_condition_set_id": 1000239, "group_id": "", "target": "Owner", "unit_tags": "1007", "unit_role": "", "unit_series": "30", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": [{"id": 1007, "name": "专用机"}], "series": {"id": 30, "world_id": 1, "name": "机动战士高达 THE ORIGIN", "desc": "宇宙世纪0068年，SIDE3，慕佐共和国。\n自护‧兹姆‧戴昆提倡进入宇宙