INSERT INTO "char_abilities" VALUES(1219000600,3,2025603,'契合度：新机动战记高达W LV3','[{"tid": 202560300, "trait_id": 202560301, "trait": {"id": 202560301, "trait_type": 17, "trait_value": 15, "desc": "搭乘单位含有「新机动战记高达W」系列时，\n对敌方造成的损伤提升15%、\n自身受到的损伤减轻15%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000044, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 8, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000044, "trait_condition_set_id": 1000044, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "2100", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 2100, "world_id": 3, "name": "新机动战记高达W", "desc": "后殖民地纪元195年，宇宙殖民地朝高压治理的地球统一联合，发动MS高达降落攻击「流星作战」。\n因为目击到参与计划的高达驾驶员希罗‧尤，莉莉娜‧德利安被迫卷入命运漩涡之中。\n希罗与其他四名驾驶员，冥冥之中彼此吸引般陆续接触，同时秘密组织OZ的总帅杜鲁斯‧国斯里达，正为了跃上历史舞台而开始进行某项作战……", "icon": "series_2100", "sort": 500, "schedule_id": 0, "scenario_stage_series_id": 2100, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_acti