INSERT INTO "char_abilities" VALUES(1431000100,3,2016801,'EX角色能力 ','[{"tid": 201680100, "trait_id": 201680101, "trait": {"id": 201680101, "trait_type": 86, "trait_value": 1, "desc": "搭乘单位含有「机动战士高达 铁血孤儿 月钢」系列，\n且自身战意为「超一击」以上时，\n「支援攻击／反击」+1次", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000300, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 1, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000300, "trait_condition_set_id": 1000300, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "4310", "unit_size": "", "tension": "Supercharged", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 4310, "world_id": 1, "name": "机动战士高达 铁血孤儿 月钢", "desc": "另外一群孤儿们的故事即将揭开序幕——\n黑手党「塔度天普」所在地，紧邻月球的艾伯兰奇殖民星上发生首领暗杀事件。\n事发后由首领独生女莉雅丽娜‧摩加顿接手塔度天普，但觊觎组织权力的各路人马，开始意图取她性命。\n阿捷‧米拉治及伏尔哥‧华伦在一番波折后，接下保护莉雅丽娜的担子，为了让她稳坐首领之位而投身这场战争之中。\n「破坏杀害家人的高达」。\n「收集家人留下的高达」。\n他们将真正意图隐藏于心，成为同一阵线……", "icon": "series_4310", "sort": 18700, "schedule_id": 0, "scenario_stage_series_id": 0, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "wea