INSERT INTO "char_abilities" VALUES(1501000200,3,2009803,'契合度：机动战士高达 水星的魔女 LV3','[{"tid": 200980300, "trait_id": 200980301, "trait": {"id": 200980301, "trait_type": 17, "trait_value": 15, "desc": "搭乘单位含有「机动战士高达 水星的魔女」系列时，\n对敌方造成的损伤提升15%、\n自身受到的损伤减轻15%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000049, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 8, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000049, "trait_condition_set_id": 1000049, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "5010", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 5010, "world_id": 0, "name": "机动战士高达 水星的魔女", "desc": "星元122年――\n大量企业扩展到宇宙，形成庞大经济圈的时代。\n一名少女从边境地区‧水星转校到MS产业中最大的企业「贝纳里特集团」旗下营运的「阿斯提卡西亚高等专门学园」。\n她的名叫做苏莱塔‧墨丘利。\n纯真的内心燃点著鲜红的亮光，少女一步步地踏进新的世界。", "icon": "series_5010", "sort": 1000, "schedule_id": 0, "scenario_stage_series_id": 5010, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "