INSERT INTO "char_abilities" VALUES(1017000800,3,2020101,'(系列条件)反击时支援防御 LV1','[{"tid": 202010101, "trait_id": 202010101, "trait": {"id": 202010101, "trait_type": 90, "trait_value": 0, "desc": "搭乘单位含有「机动战士高达0080 口袋中的战争」系列时，\n己方在对战中发动攻击，并受到敌方反击时，可进行支援防御", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000408, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 0, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000408, "trait_condition_set_id": 1000408, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "170", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 170, "world_id": 1, "name": "机动战士高达0080 口袋中的战争", "desc": "由SUNRISE企划、制作，于1989年3月23日发售的OVA作品。\n以电视动画《机动战士高达》中的一年战争末期为舞台，故事描写住在SIDE6里伯殖民卫星的一位喜欢玩战争游戏的少年阿尔弗烈德‧伊兹鲁哈与自护公国军新兵驾驶员巴纳德‧怀兹曼之间的邂逅，以及两人因之而经历的一场小规模的战事。\n此外，角川书店也于1989年10月推出以本作品为基础的小说作品。", "icon": "series_0170", "sort": 4700, "schedule_id": 0, "scenario_stage_series_id": 0, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_a