INSERT INTO "char_abilities" VALUES(1022000101,2,2019001,'(标签&系列条件)支援防御时，防御力提升 LV1','[{"tid": 201900101, "trait_id": 201900101, "trait": {"id": 201900101, "trait_type": 9, "trait_value": 15, "desc": "搭乘单位含有「机动战士高达」标签及「系列」，\n自身进行支援防御时，自身防御力提升15%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000402, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 8, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000403, "trait_condition_set_id": 1000402, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "10", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "SupportDefense", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 10, "world_id": 1, "name": "机动战士高达", "desc": "自从人类将过度繁衍的人口移民宇宙，已过了半世纪。\n数百座巨型宇宙殖民卫星悬浮在地球周围，人们以其圆筒内壁作为人造大地使用。\n半数人类成为宇宙居民，将殖民卫星当作继地球之后的第二故乡，并在此生儿育女、成长，而后死去。\n时值宇宙世纪0079年1月。\n离地球最远的宇宙都市SIDE3自立为自护公国，向地球联邦政府发起了独立战争。\n这场战争开战一个多月，规模就已庞大到造成人类总人口的半数死亡，使人们为自己的所做所为感到恐惧不已。\n而战事陷入胶著状态已过了八个多月……", "icon": "series_0010", "sort": 100, "schedule_id": 0, "scenario_stage_series_id": 10, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}]');
