INSERT INTO "char_abilities" VALUES(1230000401,3,2021501,'(系列条件)额外行动增加 LV1','[{"tid": 202150101, "trait_id": 202150101, "trait": {"id": 202150101, "trait_type": 19, "trait_value": 1, "desc": "搭乘单位含有「机动新世纪高达X」系列时，\n「额外行动」+1次", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000047, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 1, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000047, "trait_condition_set_id": 1000047, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "2300", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 2300, "world_id": 4, "name": "机动新世纪高达X", "desc": "由一个宇宙殖民地独立运动所引发，地球与宇宙殖民地的全面战争，以「殖民地坠落」让全人类的故乡──地球遭到毁灭性打击，并丧失了近乎100亿人口的形式闭幕……\n在那之后经过15年的岁月，地球环境终于进入安定期的时候，战后孤儿卡洛‧莱藉著活用自己的知识与技术，在这时代拼命求生存。\n而在某次接到的工作委托中，他遇到了有著「新人类」能力的少女，荻花‧安迪尔……\n这故事是以月亮与荒野为舞台，所描绘出的少男少女成长故事。", "icon": "series_2300", "sort": 600, "schedule_id": 0, "scenario_stage_series_id": 2300, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attac