INSERT INTO "char_abilities" VALUES(1300002502,3,2024901,'(系列条件)支援攻击／支援反击 LV1','[{"tid": 202490101, "trait_id": 202490101, "trait": {"id": 202490101, "trait_type": 51, "trait_value": 1, "desc": "搭乘单位含有「机动战士高达SEED」系列时，\n「支援攻击／反击」+1次", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000043, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 1, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000043, "trait_condition_set_id": 1000043, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "3000", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 3000, "world_id": 6, "name": "机动战士高达SEED", "desc": "宇宙纪元70年。\n这个时代，世界划分为普通人类「自然人」及基因改造人类「调整者」。\n「血腥情人节」的悲剧让两方擦枪走火，一口气转为正面武装冲突。大家深信人多势众的联合军会取得胜利，但事与愿违，战局陷入长达十一个月以上的僵局。\n另一边，漂浮于拉格朗日点5的资源卫星希奈波里斯，札多军入侵该区殖民地，试图抢夺联合军秘密制造的新型MS，就读当地工业学院的基拉‧大和也不幸被波及。\n没想到基拉却在入侵的札多军中，看见过往挚友亚斯兰‧察拉的身影……\n", "icon": "series_3000", "sort": 700, "schedule_id": 0, "scenario_stage_series_id": 3000, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_a