INSERT INTO "char_abilities" VALUES(1370004200,3,2024101,'(系列条件)支援防御 LV1','[{"tid": 202410101, "trait_id": 202410101, "trait": {"id": 202410101, "trait_type": 52, "trait_value": 1, "desc": "搭乘单位含有「机动战士高达00」系列时，\n「支援防御」+1次", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000046, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 1, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000046, "trait_condition_set_id": 1000046, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "3700", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 3700, "world_id": 0, "name": "机动战士高达00", "desc": "西元2307年。\n地球化石燃料枯竭，但人类却发现新的取代能源，利用三座顶天立地的轨道电梯，发展出大规模太阳能发电系统。\n但发电系统却只让一部分的大国及同盟国受惠，分别是美利坚合众国为首的联邦，中国、俄罗斯、印度为首的人类革新联盟，以及欧洲为首的AEU。\n三大国家群为了各自的威信和繁荣，即使到24世纪依旧不放弃零和游戏。\n于是，出现了宣示对这社会「以武力根绝战争」的私设武装组织。\n操纵机动兵器高达的他们名为天人。\n现在，高达即将对所有战争进行武力介入……", "icon": "series_3700", "sort": 800, "schedule_id": 0, "scenario_stage_series_id": 3700, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attr