INSERT INTO "char_abilities" VALUES(1378000100,3,2015302,'契合度：机动战士高达00I LV2','[{"tid": 201530200, "trait_id": 201530201, "trait": {"id": 201530201, "trait_type": 17, "trait_value": 10, "desc": "搭乘单位含有「机动战士高达00I」系列时，\n对敌方造成的损伤提升10%、\n自身受到的损伤减轻10%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000264, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 5, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000264, "trait_condition_set_id": 1000264, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "3780", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 3780, "world_id": 1, "name": "机动战士高达00I", "desc": "24世纪初期，这是一个世界以地球联邦为首迈向统合，A-Laws从旁进行武力弹劾的时代。\n作为量子型运算处理系统「韦达」的双眼，以人类之姿藏在芸芸众生中的人们，突然「觉醒」了。\n他们一瞬间从普通人生活中剥离，被带进未知世界。\n最早觉醒的「雷夫‧瑞奇塔提沃」为了找到其他六名伙伴，与泰利希拉‧赫尔菲结伴启程。\n觉醒的他们，会有何种命运等在前方……", "icon": "series_3780", "sort": 17000, "schedule_id": 0, "scenario_stage_series_id": 0, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribut