INSERT INTO "char_abilities" VALUES(1155000400,3,2027301,'契合度：机动战士高达F91 LV1','[{"tid": 202730100, "trait_id": 202730101, "trait": {"id": 202730101, "trait_type": 17, "trait_value": 5, "desc": "搭乘单位含有「机动战士高达F91」系列时，\n对敌方造成的损伤提升5%、\n自身受到的损伤减轻5%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000565, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 3, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000565, "trait_condition_set_id": 1000565, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "1620", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 1620, "world_id": 0, "name": "机动战士高达F91", "desc": "宇宙世纪123年，新兴殖民卫星群FRONTIER SIDE的其中一座殖民卫星「FRONTIER Ⅳ」突然遭到神秘MS部队入侵。\n这支自称为骷髅尖兵的部队与联邦军驻留部队展开交战，使得殖民卫星内陷入一片混乱。\n于FRONTIER Ⅳ就读高中的西布克‧阿诺，与妹妹丽兹以及同学们为远离战火而决定逃出殖民卫星。\n在过程中，一名同学赛西莉‧菲亚查德失踪。\n西布克一行人没有多余时间找她，只能搭上太空艇离开FRONTIER Ⅳ。\n此时，赛西莉与外祖父米捷亚‧罗拿，以及改名为铁假面的父亲卡罗佐‧罗拿重逢。\n她得知了自己正是率领骷髅尖兵的罗拿家一分子，并为此事苦恼不已。", "icon": "series_1620", "sort": 330, "schedule_id": 2509601801, "scenario_stage_series_id": 1620, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}, {"tid": 202730100, "trait_id": 202730102, "trait": {"id": 202730102, "trait_type": 14, "trait_value": 5, "desc": "", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000565, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 3, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000565, "trait_condition_set_id": 1000565, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "1620", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 1620, "world_id": 0, "name": "机动战士高达F91", "desc": "宇宙世纪123年，新兴殖民卫星群FRONTIER SIDE的其中一座殖民卫星「FRONTIER Ⅳ」突然遭到神秘MS部队入侵。\n这支自称为骷髅尖兵的部队与联邦军驻留部队展开交战，使得殖民卫星内陷入一片混乱。\n于FRONTIER Ⅳ就读高中的西布克‧阿诺，与妹妹丽兹以及同学们为远离战火而决定逃出殖民卫星。\n在过程中，一名同学赛西莉‧菲亚查德失踪。\n西布克一行人没有多余时间找她，只能搭上太空艇离开FRONTIER Ⅳ。\n此时，赛西莉与外祖父米捷亚‧罗拿，以及改名为铁假面的父亲卡罗佐‧罗拿重逢。\n她得知了自己正是率领骷髅尖兵的罗拿家一分子，并为此事苦恼不已。", "icon": "series_1620", "sort": 330, "schedule_id": 2509601801, "scenario_stage_series_id": 1620, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}]');
